import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { MemberCell, Standing } from './Member';
import { api, number, t, tx } from '../util';
let PageStructure;
let IndexSidebar;

/** Core components this page builds on, through the registry: some live in lazy chunks. */
async function loadCore() {
  if (PageStructure) return;
  const [structure, sidebar] = await Promise.all([flarum.reg.asyncModuleImport('flarum/forum/components/PageStructure'), flarum.reg.asyncModuleImport('flarum/forum/components/IndexSidebar')]);
  PageStructure = structure.default || structure;
  IndexSidebar = sidebar.default || sidebar;
}

/**
 * /renown: the leaderboard. All time (prestige, then XP) or this month (XP
 * earned since the 1st). Core's page structure with the forum's sidebar, so
 * any theme dresses it.
 */
export default class BoardPage extends Page {
  period = 'all';
  rows = [];
  page = 1;
  more = false;
  loading = true;
  ready = false;
  ticket = 0;
  oninit(vnode) {
    super.oninit(vnode);
    this.period = m.route.param('period') === 'month' ? 'month' : 'all';
    app.history.push('renown', tx('board.title'));
    this.bodyClass = 'App--renown';
    loadCore().then(() => {
      this.ready = true;
      m.redraw();
    });
    this.load(1);
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    app.setTitle(tx('board.title'));
    app.setTitleCount(0);
  }
  load(page) {
    const ticket = ++this.ticket;
    this.loading = true;
    if (page === 1) this.rows = [];
    api('GET', `/board?period=${this.period}&page=${page}`).then(res => {
      if (ticket !== this.ticket) return;
      this.rows = page === 1 ? res.data : [...this.rows, ...res.data];
      this.page = page;
      this.more = res.more;
      this.loading = false;
      m.redraw();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
  switchTo(period) {
    if (period === this.period) return;
    this.period = period;
    m.route.set(app.route('renown', period === 'month' ? {
      period
    } : {}), undefined, {
      replace: true
    });
    this.load(1);
  }
  view() {
    if (!this.ready) return m(LoadingIndicator, {
      display: "block"
    });
    return m(PageStructure, {
      className: "RenownPage",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "RenownBoard"
    }, m("div", {
      className: "RenownBoard-head"
    }, m("h2", {
      className: "RenownBoard-title"
    }, t('board.title')), m("div", {
      className: "RenownBoard-tabs",
      role: "tablist"
    }, ['all', 'month'].map(p => m(Button, {
      className: 'Button' + (this.period === p ? ' Button--primary' : ''),
      role: "tab",
      "aria-selected": this.period === p ? 'true' : 'false',
      onclick: () => this.switchTo(p)
    }, t('board.period_' + p))))), this.rows.length ? m("ol", {
      className: "RenownBoard-list"
    }, this.rows.map(row => m("li", {
      className: 'RenownBoard-row' + (app.session.user && Number(app.session.user.id()) === row.id ? ' is-me' : '')
    }, m("span", {
      className: "RenownBoard-pos"
    }, row.position), MemberCell(row), m("span", {
      className: "RenownBoard-standing"
    }, Standing(row)), m("span", {
      className: "RenownBoard-xp"
    }, this.period === 'month' ? t('board.gained', {
      xp: number(row.gained || 0)
    }) : t('board.xp', {
      xp: number(row.xp)
    }))))) : this.loading ? null : m("p", {
      className: "RenownBoard-empty"
    }, t('board.empty')), this.loading ? m(LoadingIndicator, {
      display: "block"
    }) : null, this.more && !this.loading ? m("div", {
      className: "RenownBoard-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(this.page + 1)
    }, t('board.more'))) : null));
  }
}
flarum.reg.add('ernestdefoe-renown', 'forum/components/BoardPage', BoardPage);