import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Emblem from '../../common/Emblem';
import { ETERNAL } from '../../common/curve';
import { tierName } from '../../common/names';
import { api, t } from '../util';
/** "Take Prestige?": what resets, what stays. Always the member's own choice. */
export default class PrestigeModal extends Modal {
  loading = false;
  className() {
    return 'RenownPrestigeModal Modal--small';
  }
  title() {
    return this.attrs.tier >= ETERNAL ? t('prestige.title_eternal') : t('prestige.title', {
      tier: tierName(this.attrs.tier)
    });
  }
  content() {
    const eternal = this.attrs.tier >= ETERNAL;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "RenownPrestigeModal-emblem"
    }, m(Emblem, {
      tier: this.attrs.tier,
      size: 96
    })), eternal ? m("p", null, t('prestige.eternal_text')) : m("ul", {
      className: "RenownPrestigeModal-list"
    }, m("li", null, m("strong", null, t('prestige.resets')), " ", t('prestige.resets_text')), m("li", null, m("strong", null, t('prestige.keeps')), " ", t('prestige.keeps_text')), m("li", null, m("strong", null, t('prestige.earns')), " ", t('prestige.earns_text', {
      tier: tierName(this.attrs.tier)
    }))), m("div", {
      className: "Form-group RenownPrestigeModal-actions"
    }, m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-star",
      loading: this.loading,
      onclick: () => this.take()
    }, t(eternal ? 'prestige.confirm_eternal' : 'prestige.confirm')), m(Button, {
      className: "Button",
      onclick: () => this.hide()
    }, t('prestige.cancel'))));
  }
  take() {
    this.loading = true;
    api('POST', '/prestige').then(res => {
      const me = app.session.user;
      if (me) {
        me.pushAttributes({
          renownLevel: res.data.level,
          renownPrestige: res.data.prestige,
          renownXp: res.data.xp,
          renownSeen: res.data.seen
        });
      }
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('prestige.done', {
        tier: tierName(res.data.prestige)
      }));
      this.attrs.onTaken();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-renown', 'forum/components/PrestigeModal', PrestigeModal);