import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { levelLabel } from '../../common/names';
import { api, number, t } from '../util';
/** Staff add or remove XP by hand. The reason is kept in the member's log. */
export default class AdjustModal extends FormModal {
  xp = Stream('');
  reason = Stream('');
  className() {
    return 'RenownAdjustModal Modal--small';
  }
  title() {
    return t('adjust.title', {
      username: this.attrs.user.displayName()
    });
  }
  content() {
    const user = this.attrs.user;
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('adjust.now', {
      rank: levelLabel(user.attribute('renownLevel') || 1),
      xp: number(user.attribute('renownXp') || 0)
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "renown-adjust-xp"
    }, t('adjust.xp')), m("input", {
      id: "renown-adjust-xp",
      className: "FormControl",
      type: "number",
      step: "1",
      bidi: this.xp,
      placeholder: "500 / -500"
    }), m("p", {
      className: "helpText"
    }, t('adjust.xp_help'))), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "renown-adjust-reason"
    }, t('adjust.reason')), m("input", {
      id: "renown-adjust-reason",
      className: "FormControl",
      maxlength: 200,
      bidi: this.reason
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit",
      loading: this.loading,
      disabled: !Number(this.xp()) || !this.reason().trim()
    }, t('adjust.submit'))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    api('POST', `/users/${this.attrs.user.id()}/adjust`, {
      xp: Number(this.xp()),
      reason: this.reason().trim()
    }).then(res => {
      this.attrs.user.pushAttributes({
        renownLevel: res.data.level,
        renownXp: res.data.xp,
        renownLifetimeXp: res.data.lifetime
      });
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('adjust.done'));
    }, this.loaded.bind(this));
  }
}
flarum.reg.add('ernestdefoe-renown', 'forum/components/AdjustModal', AdjustModal);